/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_material_update` AFTER UPDATE ON `materials` FOR EACH ROW BEGIN
    IF NEW.stock <> OLD.stock THEN
        INSERT INTO material_logs (material_name, action_type, qty_changed, new_stock)
        VALUES (
            NEW.name, 
            IF(NEW.stock > OLD.stock, 'Restock', 'Deduction'), 
            ABS(NEW.stock - OLD.stock), 
            NEW.stock
        );
    END IF;
END */;;
